B.c6b=new A.a("\u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0ba4\u0bcd \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b85\u0bb1\u0bbf\u0bb5\u0bbf\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bcd \u0bae\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd; \u0b9a\u0bb2\u0bc1\u0b95\u0bc8\u0b95\u0bb3\u0bc1\u0bae\u0bcd \u0bae\u0bc1\u0bb1\u0bcd\u0bb1\u0ba4\u0bcd\u0ba4\u0bbf\u0b9f\u0bae\u0bcd \u0b8f\u0bb1\u0bcd\u0b95\u0ba9\u0bb5\u0bc7 \u0b89\u0bb3\u0bcd\u0bb3\u0bb5\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0b85\u0bae\u0bc8\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b87\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd","\u0938\u093f\u0930\u094d\u092b\u093c \u0935\u0947 \u0938\u0942\u091a\u0928\u093e\u090f\u0901 \u091c\u094b \u0906\u092a\u0915\u0947 \u0932\u093f\u090f \u091c\u093c\u0930\u0942\u0930\u0940 \u0939\u0948\u0902; \u0911\u092b\u093c\u0930 \u0914\u0930 \u091c\u094b \u092e\u0941\u0924\u094d\u0930\u092e \u0915\u0947 \u092a\u093e\u0938 \u092a\u0939\u0932\u0947 \u0938\u0947 \u0939\u0948, \u091a\u0941\u092a \u0930\u0939\u0924\u0947 \u0939\u0948\u0902")
B.bSa=new A.a("\u0b95\u0bb5\u0ba9\u0ba4\u0bcd\u0ba4\u0bc8 \u0b87\u0baf\u0b95\u0bcd\u0b95\u0bbf \u0b92\u0bb0\u0bc1 \u0bb5\u0bbe\u0bb0\u0bae\u0bcd \u0baa\u0bbe\u0bb0\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd: \u0b85\u0bae\u0bc8\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0bcd\u0b95\u0bc1\u0bb5\u0ba4\u0bb1\u0bcd\u0b95\u0bc1 \u0bae\u0bc1\u0ba9\u0bcd \u0b8e\u0ba4\u0bc8 \u0b85\u0bae\u0bc8\u0ba4\u0bbf\u0baf\u0bbe\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0b8e\u0ba9\u0bcd\u0bb1\u0bc1 \u0b95\u0bbe\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd.","\u0915\u0935\u0928\u092e \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902 \u0914\u0930 \u090f\u0915 \u0939\u092b\u093c\u094d\u0924\u093e \u0926\u0947\u0916\u0947\u0902: \u091a\u0941\u092a \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092f\u0939 \u0926\u093f\u0916\u093e\u0924\u093e \u0939\u0948 \u0915\u093f \u0915\u094d\u092f\u093e \u091a\u0941\u092a \u0930\u0916\u0947\u0917\u093e.")
B.bYp=new A.a("\u0bae\u0bc1\u0baf\u0bb1\u0bcd\u0b9a\u0bbf \u0b9a\u0bc6\u0baf\u0bcd","\u0906\u091c\u093c\u092e\u093e\u090f\u0901")
B.bRS=new A.a("\u0b87\u0ba9\u0bcd\u0bb1\u0bc1, \u0bae\u0bc1\u0b95\u0baa\u0bcd\u0baa\u0bbf\u0bb2\u0bcd","\u0906\u091c, \u0939\u094b\u092e \u092a\u0930")
B.c3T=new A.a("\u0bae\u0bc1\u0bb1\u0bcd\u0bb1\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0bb0\u0bc1 \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0baf\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1 \u0b9a\u0bc6\u0baf\u0bcd\u0baf \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bb5\u0bc8: \u0bae\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1\u0b95\u0bb3\u0bcd, \u0baa\u0bbf\u0bb2\u0bcd\u0b95\u0bb3\u0bcd, \u0baa\u0bc7\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1, \u0bb5\u0bc7\u0bb2\u0bc8\u0b95\u0bb3\u0bcd, \u0bae\u0bc0\u0b9f\u0bcd\u0b9f\u0bbf\u0b99\u0bcd\u0b95\u0bc1\u0b95\u0bb3\u0bcd, \u0ba8\u0bc7\u0bb0 \u0bb5\u0bb0\u0bbf\u0b9a\u0bc8\u0baf\u0bbf\u0bb2\u0bcd. \u0b85\u0b99\u0bcd\u0b95\u0bc7\u0baf\u0bc7 \u0bae\u0bc1\u0b9f\u0bbf\u0ba4\u0bcd\u0ba4\u0ba4\u0bbe\u0b95\u0b95\u0bcd \u0b95\u0bc1\u0bb1\u0bbf\u0baf\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd.","\u092e\u0941\u0924\u094d\u0930\u092e \u0915\u0947 \u0939\u0930 \u0939\u093f\u0938\u094d\u0938\u0947 \u0938\u0947 \u0905\u0917\u0932\u0947 \u0915\u093e\u092e: \u0926\u0935\u093e, \u092c\u093f\u0932, \u092c\u0938, \u0918\u0930 \u0915\u0947 \u0915\u093e\u092e \u0914\u0930 \u092e\u0940\u091f\u093f\u0902\u0917, \u0938\u092e\u092f \u0915\u0947 \u0915\u094d\u0930\u092e \u092e\u0947\u0902. \u0935\u0939\u0940\u0902 \u092a\u0942\u0930\u093e \u0915\u0930\u0947\u0902.")
B.cDK=new A.a("\u0b95\u0bc1\u0b9f\u0bc1\u0bae\u0bcd\u0baa\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0bae\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0b95\u0bbf\u0bb0\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd","\u092a\u0930\u093f\u0935\u093e\u0930 \u0915\u0940 \u0926\u0935\u093e\u0907\u092f\u093e\u0901 \u0936\u0947\u092f\u0930 \u0915\u0930\u0947\u0902")
B.bRh=new A.a("\u0bae\u0bb0\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1\u0bb5\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd, \u0b95\u0bc1\u0b9f\u0bc1\u0bae\u0bcd\u0baa\u0ba4\u0bcd\u0ba4\u0bc1\u0b9f\u0ba9\u0bcd \u0baa\u0b95\u0bbf\u0bb0\u0bc1 \u0b8e\u0ba9\u0bcd\u0baa\u0ba4\u0bc8\u0ba4\u0bcd \u0ba4\u0b9f\u0bcd\u0b9f\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd. \u0b85\u0bb5\u0bb0\u0bcd\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0bae\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0ba8\u0bbf\u0ba9\u0bc8\u0bb5\u0bc2\u0b9f\u0bcd\u0b9f\u0bb2\u0bcd \u0bb5\u0bb0\u0bc1\u0bae\u0bcd, \u0b8e\u0ba8\u0bcd\u0ba4 \u0baa\u0bcb\u0ba9\u0bbf\u0bb2\u0bcd \u0b95\u0bca\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4\u0bbe\u0bb2\u0bc1\u0bae\u0bcd \u0b87\u0bb0\u0ba3\u0bcd\u0b9f\u0bbf\u0bb2\u0bc1\u0bae\u0bcd \u0ba4\u0bc6\u0bb0\u0bbf\u0baf\u0bc1\u0bae\u0bcd.","\u092e\u0930\u0941\u0924\u094d\u0924\u0941\u0935\u092e \u092e\u0947\u0902 '\u092a\u0930\u093f\u0935\u093e\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0936\u0947\u092f\u0930 \u0915\u0930\u0947\u0902' \u0926\u092c\u093e\u090f\u0901. \u0909\u0928\u094d\u0939\u0947\u0902 \u092d\u0940 \u0926\u0935\u093e \u0915\u0947 \u0930\u093f\u092e\u093e\u0907\u0902\u0921\u0930 \u092e\u093f\u0932\u0947\u0902\u0917\u0947, \u0914\u0930 \u0915\u093f\u0938\u0940 \u092d\u0940 \u092b\u093c\u094b\u0928 \u092a\u0930 \u0926\u0940 \u0917\u0908 \u0916\u0941\u0930\u093e\u0915 \u0926\u094b\u0928\u094b\u0902 \u092a\u0930 \u0926\u093f\u0916\u0947\u0917\u0940.")
B.c3s=new A.a("\u0ba8\u0ba3\u0bcd\u0baa\u0ba9\u0bbf\u0b9f\u0bae\u0bcd \u0b95\u0bc7\u0bb3\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd, AI \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbf\u0bb2\u0bcd\u0bb2\u0bc8","\u0928\u0923\u094d\u092c\u0928 \u0938\u0947 \u092a\u0942\u091b\u0947\u0902, AI \u0915\u0940 \u091c\u093c\u0930\u0942\u0930\u0924 \u0928\u0939\u0940\u0902")
B.c8N=new A.a('"\u0b95\u0b9f\u0bc8\u0b9a\u0bbf \u0bb9\u0bc8\u0ba4\u0bb0\u0bbe\u0baa\u0bbe\u0ba4\u0bcd \u0baa\u0baf\u0ba3\u0bae\u0bcd \u0b8e\u0bb5\u0bcd\u0bb5\u0bb3\u0bb5\u0bc1 \u0b86\u0ba9\u0ba4\u0bc1?", "Dolo \u0b95\u0b9f\u0bc8\u0b9a\u0bbf\u0baf\u0bbe\u0b95 \u0b8e\u0baa\u0bcd\u0baa\u0bcb\u0ba4\u0bc1 \u0bb5\u0bbe\u0b99\u0bcd\u0b95\u0bbf\u0ba9\u0bc7\u0ba9\u0bcd?", "\u0b87\u0ba8\u0bcd\u0ba4 \u0bae\u0bbe\u0ba4\u0bae\u0bcd \u0b89\u0ba3\u0bb5\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0b8e\u0bb5\u0bcd\u0bb5\u0bb3\u0bb5\u0bc1 \u0b9a\u0bc6\u0bb2\u0bb5\u0bc1?" \u2014 \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0baa\u0bcb\u0ba9\u0bbf\u0bb2\u0bc7\u0baf\u0bc7 \u0baa\u0ba4\u0bbf\u0bb2\u0bcd.','"\u092a\u093f\u091b\u0932\u0940 \u0939\u0948\u0926\u0930\u093e\u092c\u093e\u0926 \u092f\u093e\u0924\u094d\u0930\u093e \u0915\u093f\u0924\u0928\u0947 \u0915\u0940 \u092a\u0921\u093c\u0940?", "Dolo \u0906\u0916\u093c\u093f\u0930\u0940 \u092c\u093e\u0930 \u0915\u092c \u0916\u0930\u0940\u0926\u0940?", "\u0907\u0938 \u092e\u0939\u0940\u0928\u0947 \u0916\u093e\u0928\u0947 \u092a\u0930 \u0915\u093f\u0924\u0928\u093e \u0916\u0930\u094d\u091a \u0939\u0941\u0906?" \u2014 \u091c\u0935\u093e\u092c \u0906\u092a\u0915\u0947 \u092b\u093c\u094b\u0928 \u092a\u0930 \u0939\u0940.')
B.c5C=new A.a("\u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0bb5\u0bbf\u0bb0\u0bc1\u0baa\u0bcd\u0baa\u0baa\u0bcd\u0baa\u0b9f\u0bbf \u0b9f\u0bc8\u0bb2\u0bcd\u0b95\u0bb3\u0bcd","\u0905\u092a\u0928\u0940 \u092a\u0938\u0902\u0926 \u0915\u0940 \u091f\u093e\u0907\u0932\u0947\u0902")
B.cBm=new A.a("\u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1 \u0bae\u0bc7\u0bb2\u0bc7 \u0b89\u0bb3\u0bcd\u0bb3 \u0b9f\u0bc8\u0bb2\u0bcd \u0b90\u0b95\u0bbe\u0ba9\u0bc8\u0ba4\u0bcd \u0ba4\u0b9f\u0bcd\u0b9f\u0bbf, \u0baa\u0bbf\u0ba9\u0bcd \u0b92\u0bb0\u0bc1 \u0b9f\u0bc8\u0bb2\u0bc8\u0ba4\u0bcd \u0ba4\u0b9f\u0bcd\u0b9f\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd: \u0b9a\u0bbf\u0bb1\u0bbf\u0baf\u0ba4\u0bc1, \u0ba8\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4\u0bb0\u0bae\u0bcd, \u0b85\u0b95\u0bb2\u0bae\u0bcd \u0b85\u0bb2\u0bcd\u0bb2\u0ba4\u0bc1 \u0baa\u0bc6\u0bb0\u0bbf\u0baf\u0ba4\u0bc1.","\u092e\u0949\u0921\u094d\u092f\u0942\u0932 \u0915\u0947 \u090a\u092a\u0930 \u091f\u093e\u0907\u0932 \u0906\u0907\u0915\u0928 \u0926\u092c\u093e\u090f\u0901, \u092b\u093f\u0930 \u0915\u093f\u0938\u0940 \u091f\u093e\u0907\u0932 \u0915\u094b: \u091b\u094b\u091f\u093e, \u092e\u0927\u094d\u092f\u092e, \u091a\u094c\u0921\u093c\u093e \u092f\u093e \u092c\u0921\u093c\u093e.")
B.c61=new A.a("\u0baa\u0bc1\u0ba4\u0bbf\u0ba4\u0bc1: \u0b95\u0bb5\u0ba9\u0bae\u0bcd","\u0928\u092f\u093e: \u0915\u0935\u0928\u092e")
B.can=new A.a("\u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0ba4\u0bcd \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9 \u0b85\u0bb1\u0bbf\u0bb5\u0bbf\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bcd \u0bae\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd. \u0b95\u0bc1\u0bb1\u0bbf\u0baf\u0bc0\u0b9f\u0bc1\u0b95\u0bb3\u0bcd, \u0bae\u0ba9\u0bbf\u0ba4\u0bb0\u0bcd\u0b95\u0bb3\u0bcd, \u0b9a\u0bc6\u0baf\u0bcd\u0baf \u0bb5\u0bc7\u0ba3\u0bcd\u0b9f\u0bbf\u0baf\u0bb5\u0bc8 \u0b95\u0bbe\u0b9f\u0bcd\u0b9f\u0baa\u0bcd\u0baa\u0b9f\u0bc1\u0bae\u0bcd; \u0b9a\u0bb2\u0bc1\u0b95\u0bc8\u0b95\u0bb3\u0bcd, \u0bb5\u0bbf\u0bb3\u0bae\u0bcd\u0baa\u0bb0\u0b99\u0bcd\u0b95\u0bb3\u0bcd, \u0bae\u0bc1\u0bb1\u0bcd\u0bb1\u0bae\u0bcd \u0b8f\u0bb1\u0bcd\u0b95\u0ba9\u0bb5\u0bc7 \u0baa\u0ba4\u0bbf\u0bb5\u0bc1 \u0b9a\u0bc6\u0baf\u0bcd\u0baa\u0bb5\u0bc8 \u0b85\u0bae\u0bc8\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0b87\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd.","\u0938\u093f\u0930\u094d\u092b\u093c \u0935\u0947 \u0938\u0942\u091a\u0928\u093e\u090f\u0901 \u091c\u094b \u0906\u092a\u0915\u0947 \u0932\u093f\u090f \u091c\u093c\u0930\u0942\u0930\u0940 \u0939\u0948\u0902. \u0915\u094b\u0921, \u0932\u094b\u0917 \u0914\u0930 \u0915\u093e\u092e \u0926\u093f\u0916\u0924\u0947 \u0939\u0948\u0902; \u0911\u092b\u093c\u0930, \u0935\u093f\u091c\u094d\u091e\u093e\u092a\u0928 \u0914\u0930 \u091c\u094b \u092e\u0941\u0924\u094d\u0930\u092e \u092a\u0939\u0932\u0947 \u0938\u0947 \u0926\u0930\u094d\u091c \u0915\u0930\u0924\u093e \u0939\u0948, \u091a\u0941\u092a \u0930\u0939\u0924\u0947 \u0939\u0948\u0902.")
B.cGh=new A.a("\u0b95\u0bc1\u0b9f\u0bc1\u0bae\u0bcd\u0baa\u0ba4\u0bcd\u0ba4\u0bc1\u0b9f\u0ba9\u0bcd \u0baa\u0b95\u0bbf\u0bb0\u0bcd\u0bb5\u0bc1, \u0b92\u0bb0\u0bc7 \u0b87\u0b9f\u0ba4\u0bcd\u0ba4\u0bbf\u0bb2\u0bcd","\u092a\u0930\u093f\u0935\u093e\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0936\u0947\u092f\u0930, \u090f\u0915 \u0939\u0940 \u091c\u0917\u0939")
B.c37=new A.a("\u0b85\u0bae\u0bc8\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bcd, \u0b95\u0bc1\u0b9f\u0bc1\u0bae\u0bcd\u0baa\u0ba4\u0bcd\u0ba4\u0bc1\u0b9f\u0ba9\u0bcd \u0baa\u0b95\u0bbf\u0bb0\u0bc1: \u0b85\u0bb5\u0bb0\u0bcd\u0b95\u0bb3\u0bc8 \u0b92\u0bb0\u0bc1\u0bae\u0bc1\u0bb1\u0bc8 \u0b9a\u0bc7\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bc1, \u0b85\u0bb5\u0bb0\u0bcd\u0b95\u0bb3\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0baa\u0b95\u0bc1\u0ba4\u0bbf\u0b95\u0bb3\u0bc8 \u0b87\u0baf\u0b95\u0bcd\u0b95\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd: \u0bb5\u0bc0\u0b9f\u0bc1, \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0ba8\u0bbe\u0bb3\u0bcd, \u0baa\u0baf\u0ba3\u0b99\u0bcd\u0b95\u0bb3\u0bcd, \u0bae\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1\u0b95\u0bb3\u0bcd. \u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0ba9\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0b8e\u0ba4\u0bc1 \u0baa\u0bcb\u0b95\u0bbf\u0bb1\u0ba4\u0bc1 \u0b8e\u0ba9\u0bcd\u0bb1\u0bc1 \u0b9a\u0bb0\u0bbf\u0baf\u0bbe\u0b95\u0b9a\u0bcd \u0b9a\u0bca\u0bb2\u0bcd\u0bb2\u0bc1\u0bae\u0bcd.","\u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938, \u092a\u0930\u093f\u0935\u093e\u0930 \u0915\u0947 \u0938\u093e\u0925 \u0936\u0947\u092f\u0930 \u0915\u0930\u0947\u0902: \u0909\u0928\u094d\u0939\u0947\u0902 \u090f\u0915 \u092c\u093e\u0930 \u091c\u094b\u0921\u093c\u0947\u0902, \u092b\u093f\u0930 \u0935\u0947 \u0939\u093f\u0938\u094d\u0938\u0947 \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902 \u091c\u094b \u0935\u0947 \u0926\u0947\u0916\u0947\u0902\u0917\u0947: \u0918\u0930, \u0906\u092a\u0915\u093e \u0926\u093f\u0928, \u092f\u093e\u0924\u094d\u0930\u093e\u090f\u0901, \u0926\u0935\u093e\u0907\u092f\u093e\u0901. \u0939\u0930 \u090f\u0915 \u0920\u0940\u0915-\u0920\u0940\u0915 \u092c\u0924\u093e\u0924\u093e \u0939\u0948 \u0915\u093f \u0915\u094d\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948.")
B.c48=new A.a("\u0ba4\u0bbe\u0ba9\u0bbe\u0b95\u0baa\u0bcd \u0baa\u0bc1\u0ba4\u0bc1\u0baa\u0bcd\u0baa\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0b95\u0b9f\u0ba9\u0bcd\u0b95\u0bb3\u0bcd","\u0905\u092a\u0928\u0947 \u0906\u092a \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0924\u0947 \u0915\u0930\u094d\u091c\u093c")
B.cxt=new A.a("\u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0bb0\u0bc1 EMI \u0b95\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd\u0baa\u0bcb\u0ba4\u0bc1\u0bae\u0bcd \u0ba8\u0bbf\u0bb2\u0bc1\u0bb5\u0bc8\u0ba4\u0bcd \u0ba4\u0bca\u0b95\u0bc8 \u0b95\u0bc1\u0bb1\u0bc8\u0baf\u0bc1\u0bae\u0bcd. \u0bb5\u0b99\u0bcd\u0b95\u0bbf\u0baf\u0bbf\u0ba9\u0bcd \u0ba4\u0bbf\u0bb0\u0bc1\u0baa\u0bcd\u0baa\u0bbf\u0b9a\u0bcd \u0b9a\u0bc6\u0bb2\u0bc1\u0ba4\u0bcd\u0ba4\u0bc1\u0bae\u0bcd \u0b85\u0b9f\u0bcd\u0b9f\u0bb5\u0ba3\u0bc8\u0baf\u0bc8\u0b9a\u0bcd \u0b9a\u0bc7\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bbe\u0bb2\u0bcd \u0b85\u0ba4\u0bc8\u0baf\u0bc7 \u0bb0\u0bc2\u0baa\u0bbe\u0baf\u0bcd \u0bb5\u0bb0\u0bc8 \u0baa\u0bbf\u0ba9\u0bcd\u0baa\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd.","\u0939\u0930 EMI \u092d\u0930\u0928\u0947 \u092a\u0930 \u092c\u0915\u093e\u092f\u093e \u0918\u091f\u0924\u093e \u0939\u0948. \u092c\u0948\u0902\u0915 \u0915\u093e \u0930\u0940\u092a\u0947\u092e\u0947\u0902\u091f \u0936\u0947\u0921\u094d\u092f\u0942\u0932 \u091c\u094b\u0921\u093c\u0947\u0902 \u0924\u094b \u092f\u0939 \u0909\u0938\u0940 \u0915\u0947 \u0939\u093f\u0938\u093e\u092c \u0938\u0947 \u0930\u0941\u092a\u092f\u0947 \u0924\u0915 \u091a\u0932\u0924\u093e \u0939\u0948.")
