B.bWc=new A.a("\u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0bb5\u0bbe\u0bb0\u0bae\u0bcd, \u0ba4\u0bbf\u0bb0\u0bc1\u0bae\u0bcd\u0baa\u0bbf\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0ba4\u0bcd\u0ba4\u0bbe\u0bb2\u0bcd: \u0ba8\u0bbe\u0b9f\u0bcd\u0b95\u0bb3\u0bcd, \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bae\u0bcd, \u0baa\u0ba3\u0bae\u0bcd, \u0b9f\u0bc8\u0bb0\u0bbf \u0b92\u0ba9\u0bcd\u0bb1\u0bbe\u0b95","\u0906\u092a\u0915\u093e \u0939\u092b\u093c\u094d\u0924\u093e, \u092a\u0940\u091b\u0947 \u092e\u0941\u0921\u093c\u0915\u0930: \u0926\u093f\u0928, \u0928\u0940\u0902\u0926, \u092a\u0948\u0938\u093e \u0914\u0930 \u0921\u093e\u092f\u0930\u0940 \u090f\u0915 \u0938\u093e\u0925")
B.c7h=new A.a("\u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0ba4\u0bbf\u0bb0\u0bc1\u0bae\u0bcd\u0baa\u0bbf\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0bb5\u0bc8 \u0ba4\u0baf\u0bbe\u0bb0\u0bcd","\u0906\u092a\u0915\u0947 \u0939\u092b\u093c\u094d\u0924\u0947 \u092a\u0930 \u0928\u091c\u093c\u0930 \u0924\u0948\u092f\u093e\u0930 \u0939\u0948")
B.cEO=new A.a("\u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0ba8\u0bbe\u0b9f\u0bcd\u0b95\u0bb3\u0bcd, \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bae\u0bcd, \u0baa\u0ba3\u0bae\u0bcd, \u0b9f\u0bc8\u0bb0\u0bbf \u0bae\u0bb1\u0bcd\u0bb1\u0bc1\u0bae\u0bcd \u0baa\u0bb2, \u0b92\u0ba9\u0bcd\u0bb1\u0bbe\u0b95. \u0ba8\u0ba3\u0bcd\u0baa\u0ba9\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0baa\u0bcd\u0baa\u0ba4\u0bbf\u0bb2\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1 \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd AI \u0b8e\u0bb4\u0bc1\u0ba4\u0bbf\u0baf\u0ba4\u0bc1.","\u0906\u092a\u0915\u0947 \u0926\u093f\u0928, \u0928\u0940\u0902\u0926, \u092a\u0948\u0938\u093e, \u0921\u093e\u092f\u0930\u0940 \u0914\u0930 \u092c\u0939\u0941\u0924 \u0915\u0941\u091b, \u090f\u0915 \u0938\u093e\u0925. \u0928\u0928\u094d\u092c\u0928 \u091c\u094b \u0926\u0947\u0916\u0924\u093e \u0939\u0948 \u0909\u0938\u0938\u0947 \u0906\u092a\u0915\u0947 AI \u0928\u0947 \u0932\u093f\u0916\u093e.")
B.c7I=new A.a("\u0ba8\u0ba3\u0bcd\u0baa\u0ba9\u0bbe\u0bb2\u0bcd \u0b87\u0baa\u0bcd\u0baa\u0bcb\u0ba4\u0bc1 \u0b8e\u0bb4\u0bc1\u0ba4 \u0bae\u0bc1\u0b9f\u0bbf\u0baf\u0bb5\u0bbf\u0bb2\u0bcd\u0bb2\u0bc8. \u0b9a\u0bbf\u0bb1\u0bbf\u0ba4\u0bc1 \u0ba8\u0bc7\u0bb0\u0bae\u0bcd \u0b95\u0bb4\u0bbf\u0ba4\u0bcd\u0ba4\u0bc1 \u0bae\u0bc1\u0baf\u0bb2\u0bc1\u0b99\u0bcd\u0b95\u0bb3\u0bcd.","\u0928\u0928\u094d\u092c\u0928 \u0905\u092d\u0940 \u0928\u0939\u0940\u0902 \u0932\u093f\u0916 \u0938\u0915\u093e. \u0925\u094b\u0921\u093c\u0940 \u0926\u0947\u0930 \u092e\u0947\u0902 \u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0915\u0930\u0947\u0902.")
B.cor=new A.a("\u0bae\u0bc0\u0ba3\u0bcd\u0b9f\u0bc1\u0bae\u0bcd \u0bae\u0bc1\u0baf\u0bb2\u0bcd","\u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0915\u0930\u0947\u0902")
B.cds=new A.a("\u0ba4\u0bc1\u0ba3\u0bc8: \u0b9a\u0bbf\u0bb2 \u0ba8\u0bbe\u0b9f\u0bcd\u0b95\u0bb3\u0bbe\u0b95\u0b95\u0bcd \u0b95\u0ba9\u0bae\u0bbe\u0b95 \u0b87\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bbf\u0bb1\u0ba4\u0bc1. \u0baa\u0bc7\u0b9a\u0bb2\u0bbe\u0bae\u0bbe?","\u0925\u0941\u0928\u0908: \u0915\u0941\u091b \u0926\u093f\u0928 \u092d\u093e\u0930\u0940 \u0930\u0939\u0947. \u092c\u093e\u0924 \u0915\u0930\u0947\u0902?")
B.ccy=new A.a("\u0ba4\u0bc1\u0ba3\u0bc8: \u0b9a\u0bbf\u0bb2 \u0b95\u0ba9\u0bae\u0bbe\u0ba9 \u0ba8\u0bbe\u0b9f\u0bcd\u0b95\u0bb3\u0bcd, \u0b95\u0bc1\u0bb1\u0bc8\u0ba8\u0bcd\u0ba4 \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bae\u0bcd. \u0baa\u0bc7\u0b9a\u0bb2\u0bbe\u0bae\u0bbe?","\u0925\u0941\u0928\u0908: \u0915\u0941\u091b \u092d\u093e\u0930\u0940 \u0926\u093f\u0928, \u0914\u0930 \u091b\u094b\u091f\u0940 \u0930\u093e\u0924\u0947\u0902. \u092c\u093e\u0924 \u0915\u0930\u0947\u0902?")
B.co5=new A.a("\u0ba4\u0bc1\u0ba3\u0bc8\u0b95\u0bcd\u0b95\u0bc1 \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0bb5\u0bbe\u0bb0\u0bae\u0bcd \u0ba4\u0bc6\u0bb0\u0bbf\u0baf\u0bc1\u0bae\u0bcd","\u0925\u0941\u0928\u0908 \u0906\u092a\u0915\u093e \u0939\u092b\u093c\u094d\u0924\u093e \u091c\u093e\u0928\u0924\u093e \u0939\u0948")
B.c_K=new A.a("\u0b85\u0bb0\u0b9f\u0bcd\u0b9f\u0bc8\u0baf\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0bb1\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd\u0baa\u0bcb\u0ba4\u0bc1 \u0b95\u0b9f\u0ba8\u0bcd\u0ba4 \u0bb5\u0bbe\u0bb0\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0b9f\u0bc8\u0bb0\u0bbf\u0baa\u0bcd \u0baa\u0b95\u0bcd\u0b95\u0b99\u0bcd\u0b95\u0bb3\u0bc8\u0baa\u0bcd \u0baa\u0b9f\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd, \u0ba8\u0bc0\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0b95\u0bc7\u0b9f\u0bcd\u0b95\u0bc1\u0bae\u0bcd\u0baa\u0bcb\u0ba4\u0bc1 \u0bae\u0bc1\u0bb1\u0bcd\u0bb1\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0bae\u0bb1\u0bcd\u0bb1\u0bb5\u0bb1\u0bcd\u0bb1\u0bc8\u0baa\u0bcd \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd, \u0b95\u0ba9\u0bae\u0bbe\u0ba9 \u0b9a\u0bbf\u0bb2 \u0ba8\u0bbe\u0b9f\u0bcd\u0b95\u0bb3\u0bc1\u0b95\u0bcd\u0b95\u0bc1\u0baa\u0bcd \u0baa\u0bbf\u0ba9\u0bcd \u0ba8\u0bb2\u0bae\u0bcd \u0bb5\u0bbf\u0b9a\u0bbe\u0bb0\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd. \u0b92\u0bb5\u0bcd\u0bb5\u0bca\u0bb0\u0bc1 \u0b9a\u0bc6\u0baf\u0bcd\u0ba4\u0bbf\u0b95\u0bcd\u0b95\u0bc1\u0bae\u0bcd \u0b85\u0ba4\u0ba9\u0bcd \u0ba8\u0bc7\u0bb0\u0bae\u0bcd \u0b89\u0ba3\u0bcd\u0b9f\u0bc1.","\u091a\u0948\u091f \u0916\u094b\u0932\u0928\u0947 \u092a\u0930 \u092f\u0939 \u092a\u093f\u091b\u0932\u0947 \u0939\u092b\u093c\u094d\u0924\u0947 \u0915\u0947 \u0921\u093e\u092f\u0930\u0940 \u092a\u0928\u094d\u0928\u0947 \u092a\u0922\u093c\u0924\u093e \u0939\u0948, \u092a\u0942\u091b\u0928\u0947 \u092a\u0930 \u092c\u093e\u0915\u0940 \u092e\u0941\u0924\u094d\u0930\u092e \u092e\u0947\u0902 \u0926\u0947\u0916\u0924\u093e \u0939\u0948, \u0914\u0930 \u0915\u0941\u091b \u092d\u093e\u0930\u0940 \u0926\u093f\u0928\u094b\u0902 \u0915\u0947 \u092c\u093e\u0926 \u0939\u093e\u0932 \u092a\u0942\u091b\u0924\u093e \u0939\u0948. \u0939\u0930 \u0938\u0902\u0926\u0947\u0936 \u092a\u0930 \u0909\u0938\u0915\u093e \u0938\u092e\u092f \u0939\u0948.")
B.bXY=new A.a("\u0b9e\u0bbe\u0baf\u0bbf\u0bb1\u0bc1 \u0bae\u0bbe\u0bb2\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0ba4\u0bbf\u0b99\u0bcd\u0b95\u0bb3\u0bc1\u0bae\u0bcd, \u0bae\u0bc1\u0b95\u0baa\u0bcd\u0baa\u0bbf\u0bb2\u0bcd \u0b92\u0bb0\u0bc1 \u0b85\u0b9f\u0bcd\u0b9f\u0bc8: \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0ba8\u0bbe\u0b9f\u0bcd\u0b95\u0bb3\u0bcd, \u0ba4\u0bc2\u0b95\u0bcd\u0b95\u0bae\u0bcd, \u0baa\u0ba3\u0bae\u0bcd, \u0b9f\u0bc8\u0bb0\u0bbf \u0b92\u0ba9\u0bcd\u0bb1\u0bbe\u0b95, \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd AI-\u0b87\u0b9f\u0bae\u0bbf\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bc1.","\u0930\u0935\u093f\u0935\u093e\u0930 \u0936\u093e\u092e \u0914\u0930 \u0938\u094b\u092e\u0935\u093e\u0930, \u0939\u094b\u092e \u092a\u0930 \u090f\u0915 \u0915\u093e\u0930\u094d\u0921: \u0906\u092a\u0915\u0947 \u0926\u093f\u0928, \u0928\u0940\u0902\u0926, \u092a\u0948\u0938\u093e \u0914\u0930 \u0921\u093e\u092f\u0930\u0940 \u090f\u0915 \u0938\u093e\u0925, \u0906\u092a\u0915\u0947 AI \u0938\u0947.")
B.cFw=new A.a("\u0b95\u0bb5\u0ba9\u0ba4\u0bcd\u0ba4\u0bbf\u0ba9\u0bcd \u0bae\u0bbe\u0bb2\u0bc8\u0b9a\u0bcd \u0b9a\u0bc1\u0bb0\u0bc1\u0b95\u0bcd\u0b95\u0bae\u0bcd","\u0915\u0935\u0928\u092e \u0915\u093e \u0936\u093e\u092e \u0915\u093e \u0938\u093e\u0930\u093e\u0902\u0936")
B.ce4=new A.a("\u0b87\u0bb0\u0bb5\u0bc1 9 \u0bae\u0ba3\u0bbf\u0b95\u0bcd\u0b95\u0bc1, \u0b8e\u0ba4\u0bcd\u0ba4\u0ba9\u0bc8 \u0b85\u0bae\u0bc8\u0ba4\u0bbf\u0baf\u0bbe\u0b95 \u0bb5\u0bc8\u0b95\u0bcd\u0b95\u0baa\u0bcd\u0baa\u0b9f\u0bcd\u0b9f\u0ba9, \u0baa\u0bbe\u0bb0\u0bcd\u0b95\u0bcd\u0b95\u0ba4\u0bcd \u0ba4\u0b95\u0bc1\u0ba8\u0bcd\u0ba4\u0bb5\u0bc8 \u0b8f\u0ba4\u0bc7\u0ba9\u0bc1\u0bae\u0bcd. \u0ba8\u0bc0\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0b95\u0bb1\u0bcd\u0bb1\u0bc1\u0b95\u0bcd\u0b95\u0bca\u0b9f\u0bc1\u0ba4\u0bcd\u0ba4\u0bb5\u0bc8 \u0baa\u0b9f\u0bcd\u0b9f\u0bbf\u0baf\u0bb2\u0bcd\u0b95\u0bb3\u0bbf\u0bb2\u0bcd \u0bb5\u0bb0\u0bbe\u0ba4\u0bc1; \u0b89\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0b95\u0bb5\u0ba9\u0bae\u0bcd \u0ba4\u0bc7\u0bb5\u0bc8\u0baf\u0bbe\u0ba9\u0bb5\u0bc8 \u0bae\u0bc1\u0b95\u0baa\u0bcd\u0baa\u0bbf\u0bb2\u0bcd \u0bb5\u0bb0\u0bc1\u0bae\u0bcd.","\u0930\u093e\u0924 9 \u092c\u091c\u0947, \u0915\u093f\u0924\u0928\u0947 \u0936\u093e\u0902\u0924 \u0930\u0916\u0947 \u0917\u090f \u0914\u0930 \u0926\u0947\u0916\u0928\u0947 \u0932\u093e\u092f\u0915 \u0915\u094b\u0908. \u0906\u092a\u0915\u093e \u0938\u093f\u0916\u093e\u092f\u093e \u0938\u0942\u091a\u093f\u092f\u094b\u0902 \u0938\u0947 \u092c\u093e\u0939\u0930 \u0930\u0939\u0924\u093e \u0939\u0948, \u0914\u0930 \u091c\u093f\u0938\u0947 \u0906\u092a\u0915\u0940 \u091c\u093c\u0930\u0942\u0930\u0924 \u0939\u0948 \u0935\u0939 \u0939\u094b\u092e \u092a\u0930 \u0906\u0924\u093e \u0939\u0948.")
B.cmi=new A.a("\u0ba8\u0bbf\u0ba9\u0bc8\u0bb5\u0bc1\u0b95\u0bb3\u0bcd, \u0ba8\u0bc0\u0b99\u0bcd\u0b95\u0bb3\u0bcd \u0bb5\u0bbf\u0bb0\u0bc1\u0bae\u0bcd\u0baa\u0bbf\u0ba9\u0bbe\u0bb2\u0bcd","\u092f\u093e\u0926\u0947\u0902, \u0905\u0917\u0930 \u0906\u092a \u091a\u093e\u0939\u0947\u0902")
B.bP6=new A.a('\u0bae\u0bc1\u0ba8\u0bcd\u0ba4\u0bc8\u0baf \u0b86\u0ba3\u0bcd\u0b9f\u0bc1\u0b95\u0bb3\u0bbf\u0ba9\u0bcd \u0b87\u0ba4\u0bc7 \u0ba8\u0bbe\u0bb3\u0bc8\u0ba4\u0bcd \u0ba4\u0bbf\u0ba9\u0bae\u0bcd \u0b95\u0bbe\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd. \u0b9f\u0bc8\u0bb0\u0bbf \u0b85\u0bae\u0bc8\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bbf\u0bb2\u0bcd "\u0b87\u0ba4\u0bc7 \u0ba8\u0bbe\u0bb3\u0bbf\u0bb2\u0bcd" \u0b87\u0baf\u0b95\u0bcd\u0b95\u0bbf\u0ba9\u0bbe\u0bb2\u0bcd \u0bae\u0b9f\u0bcd\u0b9f\u0bc1\u0bae\u0bcd; \u0b8e\u0ba8\u0bcd\u0ba4 \u0ba8\u0bbf\u0ba9\u0bc8\u0bb5\u0bc8\u0baf\u0bc1\u0bae\u0bcd \u0ba8\u0bbf\u0bb0\u0ba8\u0bcd\u0ba4\u0bb0\u0bae\u0bbe\u0b95 \u0b92\u0ba4\u0bc1\u0b95\u0bcd\u0b95\u0bb2\u0bbe\u0bae\u0bcd.','\u0925\u093f\u0928\u092e \u092a\u093f\u091b\u0932\u0947 \u0938\u093e\u0932\u094b\u0902 \u0915\u093e \u092f\u0939\u0940 \u0926\u093f\u0928 \u0926\u093f\u0916\u093e \u0938\u0915\u0924\u093e \u0939\u0948. \u0921\u093e\u092f\u0930\u0940 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u092e\u0947\u0902 "\u0907\u0938\u0940 \u0926\u093f\u0928" \u091a\u093e\u0932\u0942 \u0915\u0930\u0947\u0902 \u0924\u092d\u0940; \u0915\u094b\u0908 \u092d\u0940 \u092f\u093e\u0926 \u0939\u092e\u0947\u0936\u093e \u0915\u0947 \u0932\u093f\u090f \u0939\u091f\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902.')
B.bVF=new A.a("\u0ba4\u0bc1\u0ba3\u0bc8 \u0bae\u0bc1\u0ba4\u0bb2\u0bbf\u0bb2\u0bcd \u0b8e\u0bb4\u0bc1\u0ba4\u0bb2\u0bbe\u0bae\u0bcd","\u0925\u0941\u0928\u0908 \u092a\u0939\u0932\u0947 \u0932\u093f\u0916 \u0938\u0915\u0924\u093e \u0939\u0948")
